import{_ as o,o as t,c as d,ai as r}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"MES 生产执行 · 基于 OpenBiz 工业域","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/mes.md","filePath":"apps/openbiz/mes.md"}'),a={name:"apps/openbiz/mes.md"};function c(s,e,i,n,p,l){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="mes-生产执行-·-基于-openbiz-工业域" tabindex="-1">MES 生产执行 · 基于 OpenBiz 工业域 <a class="header-anchor" href="#mes-生产执行-·-基于-openbiz-工业域" aria-label="Permalink to “MES 生产执行 · 基于 OpenBiz 工业域”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-mes-app</code>（<code>E:/8.cangku/for-job/openbiz-mes-app</code>）：独立后端（端口 18082）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_mes</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓 iot 域的 mes 插件<strong>仅为验证桩</strong>（<code>startProduction</code> 复用 mock 设备指令）。本试水在 <code>openbiz_mes_*</code> 表（母仓已定义）之上自建 MES 业务层，跑通真实生产闭环。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz 定义的 <code>openbiz_mes_*</code> 表（物料 / BOM / 工艺 / 生产工单 / 报工记录）+ <code>openbiz-saas-core</code> 多租户</li><li><strong>自建</strong>：工单 / 报工 Mapper / Service / Controller + 状态机 <ul><li><code>CREATED → STARTED → REPORTED → QC_PASSED → COMPLETED</code></li><li>含 <code>QC_FAILED</code> 返工、<code>CANCELLED</code> 分支</li><li>13 张业务表 · 37 个 REST 端点 · 25 个权限点（4 个岗位角色）· 37 处 <code>@PreAuthorize</code></li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p><strong>整单链</strong>：<code>create → start → report(写生产记录) → qc(pass) → complete</code>；已完成再取消被拦截 <code>ILLEGAL_TRANSITION: COMPLETED -&gt; CANCELLED</code></p><p><strong>工序链</strong>（P0 补齐的主线）：建路线 → 工单挂 <code>routing</code> → 逐道工序报工（良品 / 不良）→ 末道达标自动 <code>REPORTED</code> → 质检 → 完工；下游工序超上游产出直接 409（WIP 不变量），同 <code>eventId</code> 重发不计产。</p><p><strong>追溯链</strong>：<code>GET /api/mes/work-orders/{id}/trace</code> 一次拿全工序流水、不良明细、物料消耗、集成投递状态。</p><p><strong>集成链</strong>：</p><ul><li>MES 完工 → <code>mes_integration_outbox</code> → WMS 生产入库单（<code>source_doc_no</code> = 工单号，自动收货，重投幂等）</li><li>IIoT 设备计数增量 → MES 工序报工（<code>mes_device_cursor</code> 游标去重，超计划截断）</li></ul><p><strong>排产维度链</strong>：工单建单即带交期 / 优先级 / 产线 / 车间 / 班次，<code>GET /api/mes/work-orders/stats/dimension</code> 出四组分布 + 逾期 + 7 天临期；非法枚举当场 400。</p><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to “前端”">​</a></h2><p>三张专用业务页（不是通用表格套壳）：<strong>工序报工台</strong>（工序链进度 + 幂等键报工 + 上游余量提示）、<strong>工单追溯</strong>（四类证据分页签 + 消耗理论/实际差异率）、<strong>集成运维</strong>（联调开关 + 待发队列 + 失败重投）。通用表格页仍是元数据驱动，新增字段只改 <code>config/modules.ts</code>。</p><h2 id="验收总账" tabindex="-1">验收总账 <a class="header-anchor" href="#验收总账" aria-label="Permalink to “验收总账”">​</a></h2><p>7 套脚本 · 149 项断言 + 8 步整单流程，全部本机实跑：</p><table tabindex="0"><thead><tr><th>脚本</th><th>断言</th></tr></thead><tbody><tr><td><code>e2e_mes.py</code> / <code>e2e_standard.py</code></td><td>8 步流程 / 63（整单老基线 + 统一 REST 契约 + 排产维度 + 主数据下拉）</td></tr><tr><td><code>scripts/e2e_mes_p0.py</code></td><td>27（工序 / 追溯 / 集成 / 权限 / 分页 + 消耗口径 + 质检留痕）</td></tr><tr><td><code>scripts/verify_mes_p0_hardening.py</code></td><td>11（CAS · OK·NG 归一 · 完工禁删）</td></tr><tr><td><code>scripts/e2e_cross_system.py</code></td><td>13（MES → WMS 完工入库）</td></tr><tr><td><code>scripts/e2e_iiot_telemetry.py</code></td><td>10（IIoT → MES 遥测报工）</td></tr><tr><td><code>scripts/smoke_frontend_pages.py</code></td><td>25（前端三页取数路径 + 新增工单表单报文）</td></tr></tbody></table><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-mes-app</code>（README + <code>docs/</code> 9 篇 · 含面试问答准备包 + <code>scripts/</code> 7 套验收）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>证明 OpenBiz 工业域「实体在、服务桩」时，消费者可自行补齐真实业务流——这正是试水的意义。更进一步：这套业务层不是只能自用，它已经通过 WMS / IIoT 两个真实系统证明能跨系统协同。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',23)])])}const m=o(a,[["render",c]]);export{h as __pageData,m as default};
